+    [Description("Searches the web for information on a given query and returns a list of relevant results with titles, URLs, and descriptions.")]
+    public async Task<IReadOnlyList<SearchResult>> SearchWebAsync(
+        [Description("The search query string")] string query,
+        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
+    {
+        maxResults = Math.Clamp(maxResults, 1, 10);
+
+        if (!string.IsNullOrWhiteSpace(_braveApiKey))
+        {
+            return await SearchWithBraveAsync(query, maxResults);
+        }
+
+        return GetSimulatedResults(query, maxResults);
+    }
+
+    private async Task<IReadOnlyList<SearchResult>> SearchWithBraveAsync(string query, int maxResults)
+    {
+        var request = new HttpRequestMessage(HttpMethod.Get,
+            $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}");
+        request.Headers.Add("X-Subscription-Token", _braveApiKey);
+        request.Headers.Add("Accept", "application/json");
+
+        var response = await _httpClient.SendAsync(request);
+        response.EnsureSuccessStatusCode();
+
+        var braveResponse = await response.Content.ReadFromJsonAsync(BraveJsonContext.Default.BraveSearchResponse);
+
+        if (braveResponse?.Web?.Results is null or { Count: 0 })
+        {
+            return [new SearchResult("No results found", "", $"No web results were found for '{query}'.")];
+        }
+
+        return braveResponse.Web.Results
+            .Take(maxResults)
+            .Select(r => new SearchResult(r.Title ?? "", r.Url ?? "", r.Description ?? ""))
+            .ToList();
+    }
+
+    private static IReadOnlyList<SearchResult> GetSimulatedResults(string query, int maxResults)
+    {
+        var results = new List<SearchResult>
+        {
+            new($"Overview of {query}",
+                $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}",
+                $"A comprehensive overview covering the key concepts, history, and significance of {query}. "
+                + "This resource provides foundational knowledge and links to related topics."),
+            new($"Recent developments in {query}",
+                $"https://news.example.com/{Uri.EscapeDataString(query)}-latest",
+                $"The latest news and breakthroughs related to {query}. Covers recent research findings, "
+                + "industry trends, and expert commentary on where the field is heading."),
+            new($"{query}: A practical guide",
+                $"https://docs.example.com/guides/{Uri.EscapeDataString(query)}",
+                $"A hands-on guide to understanding and applying {query} in real-world scenarios. "
+                + "Includes step-by-step instructions, best practices, and common pitfalls to avoid."),
+            new($"Expert analysis: The future of {query}",
+                $"https://research.example.com/analysis/{Uri.EscapeDataString(query)}",
+                $"In-depth expert analysis exploring future directions of {query}. "
+                + "Discusses emerging trends, potential challenges, and opportunities for innovation."),
+            new($"{query} community and resources",
+                $"https://community.example.com/{Uri.EscapeDataString(query)}",
+                $"Community-curated resources for {query} including forums, tutorials, open-source projects, "
+                + "and recommended reading lists for beginners through advanced practitioners.")
+        };
+
+        return results.Take(maxResults).ToList();
+    }
+}
+
+public sealed record SearchResult(string Title, string Url, string Description);
+
+internal sealed class BraveSearchResponse
+{
+    [JsonPropertyName("web")]
+    public BraveWebResults? Web { get; set; }
+}
+
+internal sealed class BraveWebResults
+{
+    [JsonPropertyName("results")]
+    public List<BraveWebResult>? Results { get; set; }
+}
+
+internal sealed class BraveWebResult
+{
+    [JsonPropertyName("title")]
+    public string? Title { get; set; }
+
+    [JsonPropertyName("url")]
+    public string? Url { get; set; }
+
+    [JsonPropertyName("description")]
+    public string? Description { get; set; }
+}
+
+[JsonSerializable(typeof(BraveSearchResponse))]
+internal sealed partial class BraveJsonContext : JsonSerializerContext;
