using System.ComponentModel;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides a note-taking tool for the agent to collect, organize, and
/// review findings during research.
/// </summary>
public sealed class NoteTool
{
    private readonly List<Note> _notes = [];

    [Description("Saves a research note with a title and content. Use this to record important findings from web searches.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The content of the note with key findings")] string content,
        [Description("The source URL where this information was found")] string source)
    {
        var note = new Note(title, content, source, DateTimeOffset.UtcNow);
        _notes.Add(note);
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    [Description("Lists all saved research notes with their titles and sources.")]
    public IReadOnlyList<Note> ListNotes()
    {
        return _notes.AsReadOnly();
    }

    [Description("Retrieves the full content of all notes to help produce a final research summary.")]
    public string GetAllNotesForSummary()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        return string.Join("\n\n---\n\n", _notes.Select((n, i) =>
            $"Note {i + 1}: {n.Title}\nSource: {n.Source}\n{n.Content}"));
    }
}

public sealed record Note(string Title, string Content, string Source, DateTimeOffset SavedAt);

