using System.ClientModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;
using ResearchAgent.Tools;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// Build the chat client through MEAI abstractions
IChatClient chatClient = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(modelId)
    .AsIChatClient();

// Create tool instances with shared state
var httpClient = new HttpClient();
var webSearchTool = new WebSearchTool(httpClient);
var noteTool = new NoteTool();

// Register tools using AIFunctionFactory so the agent can call them
var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.ListNotes),
    AIFunctionFactory.Create(noteTool.GetAllNotesForSummary),
};

const string instructions = """
    You are a thorough research agent. When given a topic:
    1. Use SearchWebAsync to search for information. Run multiple searches with
       different queries to cover different angles of the topic.
    2. Use SaveNote to record key findings from each search result. Include the
       source URL so findings can be traced back.
    3. After gathering enough information (at least 3-5 notes), use
       GetAllNotesForSummary to review your collected notes.
    4. Produce a well-structured final summary with:
       - An overview paragraph
       - Key findings organized by theme
       - A list of sources consulted
    Be factual and concise. Cite sources when presenting specific claims.
    """;

// Build the agent using Microsoft Agent Framework
var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    tools: tools);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent               ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research.          ║");
Console.WriteLine("║  Type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");

if (!string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable("BRAVE_API_KEY")))
{
    Console.WriteLine("  🔍 Brave Search API detected — using live web search.");
}
else
{
    Console.WriteLine("  ℹ️  No BRAVE_API_KEY set — using simulated search results.");
    Console.WriteLine("     Set BRAVE_API_KEY for real web search.\n");
}

var session = await agent.CreateSessionAsync();

while (true)
{
    Console.Write("\n📝 Research topic: ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrWhiteSpace(topic))
    {
        continue;
    }

    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    Console.WriteLine($"\n🔬 Researching \"{topic}\"...\n");

    try
    {
        var runOptions = new ChatClientAgentRunOptions
        {
            ChatOptions = new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 4096,
            },
        };

        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic thoroughly and provide a comprehensive summary: {topic}",
            session,
            runOptions))
        {
            Console.Write(update.Text);
        }

        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
    }
}

Console.WriteLine("\nGoodbye!");

